#include <iostream>
#include <vector>

int main()
{
    std::vector<int> v{ 1, 2 };
    v.insert(v.begin(), 3, 7);           // overload (3): count, value
    for (int x : v) std::cout << x << ' ';
    std::cout << '\n';

    std::vector<int> w{ 1, 2 };
    w.insert(w.begin(), { 3, 7 });       // overload (5): an initializer list
    for (int x : w) std::cout << x << ' ';
    std::cout << '\n';
}
